# Archived source texts: strip navigation and repeated footer, preserve wording.
source=ROOT.parent/'endodont-zaloha-2026-10-23'
def archived(pattern,start_marker):
 f=next(source.glob(pattern));text=f.read_text();start=text.index(start_marker,text.index('Úvod'))
 text=text[start:];text=text.split('\nZlatí partneři')[0]
 return ''.join('<p>'+esc(line)+'</p>' for line in text.splitlines() if line.strip())
write('stanovy.html','Stanovy ČES',intro('Stanovy ČES','Znění převzaté z dosavadního webu společnosti.')+'<article class="wrap page-body prose">'+archived('*stanovy-ces.txt','Obsah:')+'</article>')
write('historie.html','Historie ČES',intro('Historie ČES','Dvacet let odborných setkání a spolupráce.')+'<article class="wrap page-body prose">'+archived('*historie-ces.txt','Historie ČES\n')+'</article>')
