issues=[2026,2025,2024,2023]
def journal_card(year):
 pdf=f'dokumenty/obcasnik-ces-{year}.pdf'
 size=(ROOT/pdf).stat().st_size/1000000
 return f'<article class="issue-card"><a class="issue-preview" href="{pdf}" aria-label="Číst Občasník ČES {year}"><img src="assets/casopis/obcasnik-{year}-mockup.jpg" alt="Občasník ČES – první {year}" width="700" height="490" loading="lazy"></a><div class="issue-copy"><p class="eyebrow">'+('Nejnovější vydání' if year==2026 else 'Archiv')+f'</p><h2>Občasník ČES · první {year}</h2><p class="muted">PDF · {size:.1f} MB</p><div class="form-actions">'+button('Číst vydání',pdf)+f'<a class="button secondary" href="{pdf}" download="Obcasnik-CES-{year}.pdf">Stáhnout PDF</a></div></div></article>'
write('obcasnik.html','Občasník ČES',intro('Občasník ČES','Všechna vydání na jednom místě. Čtěte online nebo si stáhněte PDF.')+'<section class="wrap page-body"><div class="issues-grid">'+''.join(journal_card(y) for y in issues)+'</div><section class="prose"><h2>Redakční rada</h2><p><strong>Šéfredaktor:</strong> MDDr. Antonín Tichý, Ph.D.</p><p><strong>Členové redakční rady:</strong> MDDr. Radovan Žižka, Ph.D., MDDr. Jan Lapiš a MUDr. Martin Dančík.</p></section></section>')
